D={
82129:("Passivo em manuais","Manuais usam o passivo: **must be + particípio**, **should be**, **is/are**.",[("The legs {{must be attached}} first.","As pernas devem ser fixadas primeiro."),("Batteries {{are not included}}.","As pilhas não estão incluídas."),("The machine {{should be unplugged}} first.","A máquina deve ser desligada da tomada primeiro."),("The screws {{must be tightened}}.","Os parafusos devem ser apertados.")],"Por que usar o passivo em manuais?",["Mostra o passo, sem dizer quem faz","Mostra quem faz","É mais curto sempre"],0,"O passo importa."),
82130:("Ativa × passiva","**Ativa** quando quem faz importa; **passiva** quando o fato importa ou o autor é desconhecido.",[("{{The thief stole}} the diamond.","O ladrão roubou o diamante."),("{{The diamond was stolen}}.","O diamante foi roubado."),("{{The mayor opened}} the bridge.","O prefeito inaugurou a ponte."),("The bridge {{was opened}} by the mayor.","A ponte foi inaugurada pelo prefeito.")],"Quando não sabemos quem fez, usamos…",["a ativa","a passiva","o imperativo"],1,"Passiva."),
82131:("Passiva no dia a dia","Avisos e notícias: **The flight was canceled. I was told to wait.**",[("The flight {{was canceled}} this morning.","O voo foi cancelado esta manhã."),("We {{were told}} to wait.","Mandaram-nos esperar."),("I {{was invited}} to a party.","Fui convidado para uma festa."),("The train {{was delayed}}.","O trem foi atrasado.")],"Qual está certa?",["I was invited.","I was invite.","I invited was."],0,"Was + particípio."),
82132:("Revisão da passiva","Presente: **is/are done**; passado: **was/were done**; futuro: **will be done**; modal: **must be done**.",[("He {{was arrested}} by mistake.","Ele foi preso por engano."),("They {{were forgotten}} for years.","Foram esquecidos por anos."),("The map {{was hidden}} in his cell.","O mapa estava escondido na cela dele."),("It {{will be found}} one day.","Será encontrado um dia.")],"Qual é futuro passivo?",["It was found.","It will be found.","It is found."],1,"Will be + particípio."),
82133:("Discurso indireto","Recue o tempo: *am → was*, *will → would*. **Tell** pede pessoa; **say** não.",[("She said that she {{was}} tired.","Ela disse que estava cansada."),("He {{told me}} that he was busy.","Ele me disse que estava ocupado."),("They said they {{would come}}.","Eles disseram que viriam."),("He {{said}} he had finished.","Ele disse que tinha terminado.")],"“I will come” → He said he ___ come.",["will","would","wills"],1,"Will → would."),
930029:("burn the midnight oil","**Burn the midnight oil** = trabalhar até tarde; **go the extra mile** = esforçar-se mais; **give it your all** = dar o máximo.",[("I'm {{burning the midnight oil}} to finish.","Estou trabalhando até tarde para terminar."),("He always {{goes the extra mile}}.","Ele sempre se esforça além do esperado."),("{{Give it your all}}!","Dê o seu máximo!"),("She {{works hard}}.","Ela trabalha duro.")],"“Go the extra mile” significa…",["andar mais","esforçar-se mais","viajar"],1,"Esforço extra."),
82134:("Perguntas indiretas (sim/não)","Use **if / whether** e ordem de afirmação: *She asked if I liked books.*",[("She asked {{if}} I liked books.","Ela perguntou se eu gostava de livros."),("He wondered {{whether}} it was raining.","Ele se perguntou se estava chovendo."),("I asked {{if}} the shop was open.","Perguntei se a loja estava aberta."),("She asked {{whether}} I was ready.","Ela perguntou se eu estava pronto.")],"Qual está certa?",["She asked if did I like it.","She asked if I liked it.","She asked did I like it."],1,"Sem do/did."),
82135:("Perguntas wh indiretas","**Wh + ordem de afirmação**, sem do/does/did.",[("He asked {{where I lived}}.","Ele perguntou onde eu morava."),("She wanted to know {{what time it was}}.","Ela quis saber que horas eram."),("I asked {{how much it cost}}.","Perguntei quanto custava."),("He asked {{who I was}}.","Ele perguntou quem eu era.")],"Qual está certa?",["He asked where did I live.","He asked where I lived.","He asked where I live did."],1,"Ordem de afirmação."),
82136:("Ordens reportadas","**Told/asked + pessoa + to + verbo**; negativo: **not to**.",[("The mayor {{told them to leave}}.","O prefeito mandou eles saírem."),("She {{asked me to wait}} here.","Ela me pediu para esperar aqui."),("He {{told me not to be}} late.","Ele me disse para não me atrasar."),("They {{asked us to keep}} quiet.","Pediram-nos para ficar quietos.")],"“Don't run!” → She told me ___.",["to not run","not to run","don't run"],1,"Not to + verbo."),
82137:("say × tell","**Say** não leva pessoa; **tell** leva. *Tell a lie, tell the truth, tell a story*.",[("He {{said}} hello to me.","Ele me disse olá."),("He {{told me}} the truth.","Ele me contou a verdade."),("Don't {{tell a lie}}.","Não conte uma mentira."),("She {{told}} us a story.","Ela nos contou uma história.")],"Qual está certa?",["He said me the truth.","He told me the truth.","He told the truth me."],1,"Told me."),
930030:("surpresa","**No way! Are you serious? I can't believe it!**",[("{{No way}}! Really?","Não acredito! Sério?"),("{{Are you serious}}?","Você está falando sério?"),("{{I can't believe it}}.","Não consigo acreditar."),("{{What a shock}}!","Que choque!")],"Qual expressa surpresa?",["No way!","See you.","Thanks."],0,"No way."),
82138:("Palavras de tempo no discurso indireto","**Today → that day; yesterday → the day before; tomorrow → the next day; now → then**.",[("“I called {{yesterday}}.” → He had called {{the day before}}.","Eu liguei ontem → Ele tinha ligado no dia anterior."),("“I'll come {{tomorrow}}.” → She said she'd come {{the next day}}.","Venho amanhã → Ela disse que viria no dia seguinte."),("“{{Now}} I know.” → He said he knew {{then}}.","Agora sei → Ele disse que sabia então."),("“{{Last week}}…” → {{the week before}}","Semana passada → a semana anterior")],"“Tomorrow” → …",["the day before","the next day","that day"],1,"The next day."),
82139:("Verbos que reportam","**admit/deny/suggest + -ing**; **promise/refuse + to**; **warn + pessoa + not to**.",[("He {{admitted making}} a mistake.","Ele admitiu ter cometido um erro."),("She {{denied taking}} the money.","Ela negou ter pegado o dinheiro."),("He {{promised to help}}.","Ele prometeu ajudar."),("He {{warned us not to enter}}.","Ele nos avisou para não entrar.")],"Qual está certa?",["She promised helping.","She promised to help.","She promised help."],1,"Promise + to."),
82140:("Passar um recado","**Told/asked me to** e **said (that)** para passar um recado.",[("He {{asked me to tell}} you.","Ele pediu que eu dissesse a você."),("He {{said it was}} urgent.","Ele disse que era urgente."),("Please {{ask her to call}} me back.","Peça a ela que me ligue de volta."),("Mr. Lee {{called}}.","O Sr. Lee ligou.")],"“Urgent” significa…",["urgente","longo","educado"],0,"Urgente."),
82141:("O que ele disse?","Para confirmar: **What did he say? Did you say…? I thought he said…**",[("Sorry, {{what did he say}}?","Desculpe, o que ele disse?"),("He {{said he had just arrived}}.","Ele disse que tinha acabado de chegar."),("{{Could you repeat that}}, please?","Poderia repetir, por favor?"),("{{I thought he said}} Friday.","Achei que ele tinha dito sexta.")],"Como pedir para repetir?",["Could you repeat that?","Say not.","What he?"],0,"Could you repeat?"),
82142:("it seems / apparently","Sem certeza: **It seems that…**, **apparently**, **reportedly**.",[("{{It seems that}} he resigned.","Parece que ele pediu demissão."),("{{Apparently}}, the flight was delayed.","Aparentemente, o voo atrasou."),("{{It was reported that}} two people were hurt.","Foi noticiado que duas pessoas se feriram."),("{{Reportedly}}, it's true.","Segundo relatos, é verdade.")],"“Apparently” indica…",["certeza total","informação não confirmada","uma ordem"],1,"Ao que parece."),
930031:("pass on / pass out","**Pass on** = repassar; **pass out** = desmaiar; **pass away** = falecer; **pass by** = passar por.",[("Please {{pass on}} the news.","Por favor, repasse a notícia."),("He {{passed out}} in the hall.","Ele desmaiou no corredor."),("I {{passed by}} the hospital.","Passei pelo hospital."),("Her grandpa {{passed away}}.","O avô dela faleceu.")],"“Pass out” significa…",["desmaiar","entregar","passar"],0,"Desmaiar."),
82143:("Reclamar indiretamente","**Complained that + frase** ou **complain about + nome**.",[("He {{complained that}} the office was cold.","Ele reclamou que o escritório estava frio."),("She said the kitchen {{was}} dirty.","Ela disse que a cozinha estava suja."),("They {{complained about}} the noise.","Eles reclamaram do barulho."),("He {{complained}} loudly.","Ele reclamou alto.")],"Qual está certa?",["He complained about the noise.","He complained to the noise.","He complained the noise."],0,"Complain about."),
82144:("Revisão do discurso indireto","Recue o tempo; **if/whether** (sim/não); **wh + afirmação**; **told/asked + pessoa + to**.",[("He said that he {{was}} tired.","Ele disse que estava cansado."),("She asked {{if}} I liked parties.","Ela perguntou se eu gostava de festas."),("He wanted to know {{who I was}}.","Ele quis saber quem eu era."),("She told me {{to wait}}.","Ela me mandou esperar.")],"“Will” no discurso indireto vira…",["would","was","did"],0,"Would."),
81120:("who / that / where","**Who** = pessoas; **that** = coisas; **where** = lugares.",[("Ann is the woman {{who}} works late.","A Ann é a mulher que trabalha até tarde."),("This is the lamp {{that}} I like.","Esta é a luminária de que eu gosto."),("That is the office {{where}} I work.","Aquele é o escritório onde trabalho."),("He's the colleague {{who}} sits here.","Ele é o colega que senta aqui.")],"Complete: “The place ___ I live is quiet.”",["who","where","which person"],1,"Lugar: where."),
82145:("Relativas que definem","**Who** (pessoa), **which** (coisa), **that** (ambos), **whose** (posse). Sem vírgula.",[("The woman {{who}} lives upstairs is my teacher.","A mulher que mora em cima é minha professora."),("The house {{which}} stands on the hill is old.","A casa que fica na colina é velha."),("The man {{whose}} car was stolen called.","O homem cujo carro foi roubado ligou."),("The book {{that}} I read was great.","O livro que li era ótimo.")],"“Whose” indica…",["posse","lugar","tempo"],0,"Posse."),
81262:("who / which","**Who** para pessoas; **which** para coisas.",[("Steve is the person {{who}} plans.","O Steve é a pessoa que planeja."),("This is the idea {{which}} is good.","Esta é a ideia que é boa."),("{{Who}} is the leader?","Quem é o líder?"),("This is the task {{which}} is easy.","Esta é a tarefa que é fácil.")],"Complete: “The man ___ called is my boss.”",["who","which","where"],0,"Pessoa: who."),
930032:("however / on the other hand","**However** e **on the other hand** abrem a frase; **although / whereas** ligam duas ideias; **despite** + substantivo.",[("{{However}}, it is risky.","No entanto, é arriscado."),("{{On the other hand}}, I want stability.","Por outro lado, quero estabilidade."),("{{Although}} it is risky, I like action.","Embora seja arriscado, gosto de ação."),("He likes sea, {{whereas}} I like mountains.","Ele gosta do mar, enquanto eu gosto de montanhas.")],"“Whereas” expressa…",["contraste","tempo","causa"],0,"Contraste."),
82146:("Relativas não restritivas","Informação extra **entre vírgulas**; não use *that*.",[("My brother, {{who}} lives in London, is a doctor.","Meu irmão, que mora em Londres, é médico."),("The ball, {{which}} was crowded, ended late.","O baile, que estava lotado, terminou tarde."),("Paris, {{which}} I love, is huge.","Paris, que eu amo, é enorme."),("Tom, {{whose}} dog barks, is my neighbor.","Tom, cujo cachorro late, é meu vizinho.")],"Qual está certa?",["My brother, that lives in Rome, is a pilot.","My brother, who lives in Rome, is a pilot.","My brother who, lives in Rome is a pilot."],1,"Who com vírgulas."),
82147:("where / when / why","**Where** (lugar), **when** (tempo), **why** (motivo) ligam a frase.",[("This is the town {{where}} I was born.","Esta é a cidade onde nasci."),("I remember the day {{when}} we met.","Lembro do dia em que nos conhecemos."),("That is the reason {{why}} I came back.","Esse é o motivo pelo qual voltei."),("It's the place {{where}} we met.","É o lugar onde nos conhecemos.")],"Complete: “The reason ___ I left is simple.”",["where","when","why"],2,"Reason: why."),
82148:("Omitir o pronome","Quando é **objeto**, o pronome pode sumir: *The man (who) I met*.",[("The man {{I met}} is my uncle.","O homem que conheci é meu tio."),("The hat {{she wanted}} was red.","O chapéu que ela queria era vermelho."),("I told him everything {{I knew}}.","Contei a ele tudo o que sabia."),("The man {{who lives here}} is kind.","O homem que mora aqui é gentil.")],"Em qual frase NÃO dá para omitir o pronome?",["The man (who) I met","The man who lives here","The hat (that) she wanted"],1,"Quando é sujeito."),
82149:("although / even though","**Although / though / even though** ligam ideias que contrastam; não use *but* junto.",[("{{Although}} he was tired, he went to work.","Embora estivesse cansado, ele foi trabalhar."),("She smiled {{even though}} she was sad.","Ela sorriu embora estivesse triste."),("He went, {{though}}.","Ele foi, mesmo assim."),("{{Even though}} it rained, we played.","Mesmo chovendo, jogamos.")],"Qual está certa?",["Although he was tired, but he went.","Although he was tired, he went.","Although he tired, he went."],1,"Sem but."),
82150:("despite / in spite of","**Despite / in spite of** + substantivo ou **-ing**; para frase use **although**.",[("{{Despite}} the rain, we went out.","Apesar da chuva, saímos."),("{{In spite of}} being tired, I went.","Apesar de cansado, fui."),("{{Although}} it was raining, we went.","Embora chovesse, fomos."),("{{Despite}} the cost, he bought it.","Apesar do custo, ele comprou.")],"Qual está certa?",["Despite it was raining","Despite the rain","Despite of the rain"],1,"Despite + nome."),
930033:("collocations com pay","**Pay attention, pay a visit, pay a compliment, pay the price**.",[("Please {{pay attention}} in class.","Preste atenção na aula."),("I'll {{pay you a visit}} on Sunday.","Farei uma visita a você no domingo."),("You will {{pay the price}}.","Você vai pagar o preço."),("She {{paid me a compliment}}.","Ela me elogiou.")],"Qual está certa?",["make attention","pay attention","do attention"],1,"Pay attention."),
82151:("however / nevertheless","**However** e **nevertheless** contrastam frases; vêm no início, com vírgula.",[("It was hard. {{However}}, she tried.","Foi difícil. No entanto, ela tentou."),("The odds were low; {{nevertheless}}, she volunteered.","As chances eram baixas; mesmo assim, ela se voluntariou."),("{{On the other hand}}, it was fun.","Por outro lado, foi divertido."),("It rained. {{Nevertheless}}, we went.","Choveu. Ainda assim, fomos.")],"“Nevertheless” significa…",["além disso","mesmo assim","portanto"],1,"Mesmo assim."),
82152:("besides / moreover","Para acrescentar: **besides, moreover, in addition, also**.",[("I'm tired. {{Besides}}, it's late.","Estou cansado. Além disso, é tarde."),("The hotel is cheap. {{Moreover}}, it's clean.","O hotel é barato. Além disso, é limpo."),("We need chairs. {{In addition}}, we need tables.","Precisamos de cadeiras. Além disso, de mesas."),("She is kind. {{Also}}, she is funny.","Ela é gentil. Também é engraçada.")],"“Moreover” significa…",["além disso","contudo","porque"],0,"Acrescenta."),
82153:("because of / therefore","**Because of / due to** + nome dão a causa; **therefore / as a result** dão o resultado.",[("{{Because of}} the rain, the game was canceled.","Por causa da chuva, o jogo foi cancelado."),("The delay was {{due to}} a strike.","O atraso foi devido a uma greve."),("It rained; {{therefore}}, we stayed home.","Choveu; portanto, ficamos em casa."),("{{As a result}}, we were late.","Como resultado, nos atrasamos.")],"Qual dá o resultado?",["because of","therefore","due to"],1,"Therefore."),
82154:("Finalidade","**To / in order to / so as to + verbo**; negativo: **in order not to / so as not to**; **so that + frase**.",[("I went to the woods {{to think}}.","Fui à floresta para pensar."),("I saved money {{in order to travel}}.","Economizei para viajar."),("He wrote clearly {{so as not to confuse}} anyone.","Escreveu com clareza para não confundir ninguém."),("I study {{so that}} I can pass.","Estudo para poder passar.")],"Qual está certa?",["I went there for buy bread.","I went there to buy bread.","I went there for to buy."],1,"To + verbo."),
82155:("Organizar ideias","**First of all, then/next, after that, finally/lastly, to sum up**.",[("{{First of all}}, I built a cabin.","Primeiro de tudo, construí uma cabana."),("{{Then}}, I planted some beans.","Depois, plantei feijão."),("{{After that}}, I started to write.","Depois disso, comecei a escrever."),("{{To sum up}}, it was worth it.","Resumindo, valeu a pena.")],"“To sum up” introduz…",["o começo","o resumo","uma dúvida"],1,"Resumo."),
930034:("pull over / pull out","**Pull over** = encostar; **pull out** = sair; **pull up** = parar; **pull through** = superar.",[("{{Pull over}} now.","Encoste agora."),("{{Pull out}} at the station.","Saia na estação."),("The car {{pulled up}} slowly.","O carro parou devagar."),("We'll {{pull through}} the crisis.","Vamos superar a crise.")],"“Pull over” significa…",["encostar","puxar","sair do carro"],0,"Encostar."),
82156:("as / since / because","**Because** dá a razão direta; **since / as** abrem a frase e dão razão já conhecida.",[("He stole bread {{because}} he was hungry.","Ele roubou pão porque estava com fome."),("{{Since}} it was raining, we stayed home.","Como estava chovendo, ficamos em casa."),("{{As}} it was late, we left.","Como era tarde, saímos."),("I stayed {{because}} I wanted to.","Fiquei porque quis.")],"Qual abre a frase com razão já conhecida?",["because","since","so"],1,"Since."),
82157:("both / either / neither … nor","**Both … and** = tanto … quanto; **either … or** = ou … ou; **neither … nor** = nem … nem.",[("{{Both}} Dum {{and}} Dee are friendly.","Tanto Dum quanto Dee são amigáveis."),("You can take {{either}} road.","Você pode pegar qualquer estrada."),("{{Neither}} of them wanted to stop.","Nenhum deles quis parar."),("He wants {{neither}} tea {{nor}} coffee.","Ele não quer nem chá nem café.")],"“Neither … nor” é…",["afirmativo","negativo","condicional"],1,"Já é negativo."),
82158:("so / such … that","**So + adjetivo**, **such (a) + substantivo**, e **that** mostra o resultado.",[("The castle was {{so}} dark {{that}} we couldn't see.","O castelo era tão escuro que não víamos."),("It was {{such a}} dark night {{that}} we got lost.","Era uma noite tão escura que nos perdemos."),("The house was {{so}} silent {{that}} I felt afraid.","A casa estava tão silenciosa que senti medo."),("It was {{such}} a big storm.","Foi uma tempestade enorme.")],"Complete: “It was ___ cold day.”",["so","such a","too"],1,"Substantivo: such a."),
81292:("so / such","**So + adjetivo**; **such a + substantivo**.",[("The bed is {{so}} soft.","A cama é tão macia."),("It is {{such a}} comfortable bed.","É uma cama tão confortável."),("I am {{so}} sleepy.","Estou com tanto sono."),("It's {{such a}} nice pillow.","É um travesseiro tão bom.")],"Qual está certa?",["so a comfortable bed","such a comfortable bed","so comfortable a bed"],1,"Such a."),
82159:("too / enough","**Too + adjetivo** (problema); **adjetivo + enough** (suficiente).",[("This bag is {{too}} heavy for me.","Esta bolsa é pesada demais para mim."),("He is strong {{enough}} to lift it.","Ele é forte o bastante para levantá-la."),("I don't have {{enough}} money.","Não tenho dinheiro suficiente."),("It's {{too}} late to call.","É tarde demais para ligar.")],"Qual está certa?",["enough strong","strong enough","enough of strong"],1,"Adjetivo + enough."),
930035:("pulling your leg","**Pull someone's leg** = brincar; **break the ice** = descontrair; **a piece of cake** = fácil; **you're joking**.",[("Are you {{pulling my leg}}?","Você está brincando comigo?"),("Let me {{break the ice}} at the party.","Deixe-me descontrair a festa."),("It is {{a piece of cake}}.","É moleza."),("{{You're joking}}!","Você está brincando!")],"“Pull my leg” significa…",["me enganar de brincadeira","me puxar","me machucar"],0,"Brincadeira."),
82160:("Revisão: relativas e conectores","**Who/which/whose**, vírgulas para extra, **although/despite**, **because/since**, **so/therefore**.",[("The woman {{who}} runs the house is strict.","A mulher que administra a casa é rígida."),("She smiled, {{although}} she was upset.","Ela sorriu, embora estivesse chateada."),("{{Despite}} her smile, she was sad.","Apesar do sorriso, ela estava triste."),("She was tired, {{so}} she left.","Estava cansada, então saiu.")],"Qual dá o resultado?",["since","so","although"],1,"So."),
82161:("verbo + -ing","**Enjoy, avoid, mind, finish, suggest, imagine, keep, can't stand + -ing**.",[("I {{enjoy reading}} at night.","Gosto de ler à noite."),("He {{avoids talking}} about it.","Ele evita falar sobre isso."),("Do you {{mind opening}} the window?","Você se importa de abrir a janela?"),("I {{can't stand waiting}}.","Não suporto esperar.")],"Qual está certa?",["I enjoy to read.","I enjoy reading.","I enjoy read."],1,"Enjoy + -ing."),
82162:("verbo + to","**Decide, hope, plan, want, need, refuse, promise, learn, manage + to + verbo**.",[("I {{decided to travel}}.","Decidi viajar."),("We {{plan to visit}} Rome.","Planejamos visitar Roma."),("He {{refused to leave}} home.","Ele se recusou a sair de casa."),("They {{managed to find}} the treasure.","Eles conseguiram achar o tesouro.")],"Qual está certa?",["I decided traveling.","I decided to travel.","I decided travel."],1,"Decide + to."),
82163:("stop / remember","**Stop to + verbo** = parar para; **stop + -ing** = parar de. **Remember to** = não esquecer; **remember -ing** = lembrar do que fez.",[("I {{stopped to rest}}.","Parei para descansar."),("I {{stopped smoking}}.","Parei de fumar."),("{{Remember to lock}} the door.","Lembre-se de trancar a porta."),("I {{remember locking}} it.","Lembro de ter trancado.")],"“He stopped smoking” significa…",["Ele parou para fumar.","Ele parou de fumar.","Ele fumou."],1,"Parou de."),
82164:("try to × try -ing","**Try to** = esforçar-se; **try + -ing** = testar.",[("I {{tried to open}} the door.","Tentei abrir a porta."),("{{Try adding}} more salt.","Tente acrescentar mais sal."),("She {{tries to arrive}} on time.","Ela tenta chegar na hora."),("{{Try restarting}} the app.","Tente reiniciar o aplicativo.")],"“Try adding salt” = …",["Faça um esforço.","Faça um teste.","Não faça."],1,"Experimento."),
930036:("plug in / turn on","**Plug in** = ligar na tomada; **turn on/off**; **switch off**; **break down** = quebrar.",[("{{Plug in}} the TV.","Ligue a TV na tomada."),("{{Turn on}} the lights.","Acenda as luzes."),("{{Switch off}} the oven.","Desligue o forno."),("My car {{broke down}} yesterday.","Meu carro quebrou ontem.")],"“Break down” significa…",["quebrar","quebrar nozes","construir"],0,"Quebrar (pane)."),
82165:("let / make / help","**Let** = permitir; **make** = obrigar; **help** = ajudar. Depois: pessoa + **verbo base** (sem to).",[("My parents {{let me stay}} out until ten.","Meus pais me deixam ficar fora até as dez."),("The teacher {{makes us do}} homework.","A professora nos obriga a fazer lição."),("She {{helped me carry}} it.","Ela me ajudou a carregar."),("The film {{makes me cry}}.","O filme me faz chorar.")],"Qual está certa?",["She makes me to cry.","She makes me cry.","She makes me crying."],1,"Make + verbo base."),
82166:("preposição + -ing","Depois de **preposição**, o verbo vai no **-ing**.",[("He is good {{at telling}} stories.","Ele é bom em contar histórias."),("I'm afraid {{of speaking}} in public.","Tenho medo de falar em público."),("Don't leave {{without saying}} goodbye.","Não saia sem se despedir."),("{{Instead of waiting}}, go!","Em vez de esperar, vá!")],"Qual está certa?",["interested in learn","interested in learning","interested to learn"],1,"In + -ing."),
82167:("it's worth / no use","**It's worth, it's no use, can't help, there's no point in + -ing**.",[("{{It's worth trying}} again.","Vale a pena tentar de novo."),("{{It's no use crying}} over it.","Não adianta chorar por isso."),("I {{can't help laughing}}.","Não consigo parar de rir."),("{{There's no point in waiting}}.","Não adianta esperar.")],"“It's no use” significa…",["não adianta","é útil","use isto"],0,"Não adianta."),
82168:("used to × be used to","**Used to + verbo** = hábito passado; **be used to + -ing** = estar acostumado; **get used to** = acostumar-se.",[("I {{used to live}} in Tokyo.","Eu morava em Tóquio."),("I'm {{used to}} the noise.","Estou acostumado ao barulho."),("She is {{used to waking}} up early.","Ela está acostumada a acordar cedo."),("I'm {{getting used to}} the cold.","Estou me acostumando ao frio.")],"Qual está certa?",["I am used to wake up early.","I am used to waking up early.","I used to waking up early."],1,"Be used to + -ing."),
81294:("be used to","**Be used to + -ing/nome** = estar acostumado; **get used to** = acostumar-se.",[("I {{am used to}} the food.","Estou acostumado à comida."),("I {{am not used to}} the language.","Não estou acostumado à língua."),("I {{am getting used to}} the city.","Estou me acostumando à cidade."),("I {{am not used to walking}} so much.","Não estou acostumado a caminhar tanto.")],"“Get used to” significa…",["acostumar-se","usar","acostumar alguém"],0,"Acostumar-se."),
930037:("show up / show off","**Show up** = aparecer; **show off** = se exibir; **show around** = guiar; **show in** = conduzir para dentro.",[("She {{showed up}} on time.","Ela apareceu na hora."),("She loves to {{show off}} her dress.","Ela adora exibir o vestido."),("Let me {{show you around}}.","Deixe-me mostrar o lugar."),("{{Show them in}}, please.","Conduza-os para dentro, por favor.")],"“Show up” significa…",["aparecer","exibir","mostrar"],0,"Aparecer."),
82169:("adjetivo + to","Muitos adjetivos pedem **to + verbo**: *happy, glad, pleased, ready, surprised, sorry, proud, easy*.",[("I'm {{pleased to meet}} you.","Prazer em conhecer você."),("Are you {{ready to start}}?","Você está pronto para começar?"),("She was {{surprised to see}} him.","Ela ficou surpresa ao vê-lo."),("It's {{easy to use}}.","É fácil de usar.")],"Qual está certa?",["I'm happy helping.","I'm happy to help.","I'm happy for help."],1,"Happy to help."),
82170:("like / start com -ing ou to","**Like, love, hate, prefer, start, begin, continue** aceitam **-ing** ou **to**; *would like* só aceita **to**.",[("I {{like reading}}.","Gosto de ler."),("She {{loves to write}} stories.","Ela adora escrever histórias."),("It {{started raining}}.","Começou a chover."),("I'd {{like to read}} now.","Gostaria de ler agora.")],"Qual está certa?",["I'd like reading.","I'd like to read.","I'd like read."],1,"Would like + to."),
82171:("objeto + infinitivo","**Want/ask/tell/expect/warn/allow/advise + pessoa + to + verbo**.",[("I {{want you to come}}.","Quero que você venha."),("She {{asked him to help}}.","Ela pediu a ele que ajudasse."),("He {{told us to wait}} here.","Ele nos mandou esperar aqui."),("They {{allowed me to leave}}.","Eles me deixaram sair.")],"Qual está certa?",["I want that you come.","I want you to come.","I want you come."],1,"Want + pessoa + to."),
82172:("-ing como sujeito","O **-ing** pode ser sujeito e leva verbo no singular.",[("{{Swimming}} is good for your health.","Nadar faz bem à saúde."),("{{Reading every day}} is important.","Ler todo dia é importante."),("{{Walking in the woods}} relaxes me.","Caminhar na floresta me relaxa."),("{{Saving money}} matters.","Economizar importa.")],"Qual está certa?",["Swimming are good.","Swimming is good.","Swim is good."],1,"Singular: is."),
930038:("Checar compreensão","**Do you follow me? Could you repeat that? So you mean…?**",[("{{Do you follow me}}?","Está me acompanhando?"),("{{Could you repeat that}}, please?","Pode repetir, por favor?"),("{{So you mean}} I should stay calm?","Então você quer dizer que devo ficar calmo?"),("{{I get it}}.","Entendi.")],"“Do you follow me?” pergunta…",["se você entendeu","se você corre","se você sai"],0,"Compreensão."),
82173:("to + verbo: finalidade","Para dizer **para quê**, use **to + verbo**.",[("I went to the market {{to buy}} bread.","Fui ao mercado para comprar pão."),("I study {{to learn}} English.","Estudo para aprender inglês."),("She called me {{to say}} hello.","Ela me ligou para dizer olá."),("Why did you go? {{To see}} him.","Por que foi? Para vê-lo.")],"Qual está certa?",["for buying bread","to buy bread","for to buy bread"],1,"To + verbo."),
82174:("Revisão: padrões verbais","**Enjoy + -ing**, **want + to**, **ask + pessoa + to**, **let/make + base**, **stop to × stop -ing**.",[("I {{enjoy swimming}}.","Gosto de nadar."),("I {{want to learn}} French.","Quero aprender francês."),("She {{asked him to help}} her.","Ela pediu a ele que a ajudasse."),("They {{let us go}}.","Eles nos deixaram ir.")],"Qual está certa?",["She let me to go.","She let me go.","She let me going."],1,"Let + base."),
}
